function toast(t){const el=document.createElement('div');el.className='toast';el.textContent=t;document.body.appendChild(el);setTimeout(()=>el.remove(),2600)}
function status(t){$('#statusText').textContent=t}
function byId(id){return state.components.find(c=>c.id===id)}
function rayById(id){return result.segments.find(r=>r.id===id)}
function commit(){const next=JSON.stringify(state);if(next===baseline)return;if(baseline){history.push(baseline);if(history.length>60)history.shift()}future=[];baseline=next;dirty=true;syncHistory()}
function syncHistory(){$('#undoBtn').disabled=!history.length;$('#redoBtn').disabled=!future.length}
function clearSelection(){selection.clear();selectedRay=null;selectedBoard=null}
function undo(redo=false){const from=redo?future:history,to=redo?history:future;if(!from.length)return;to.push(JSON.stringify(state));const log=state.labLog;state=JSON.parse(from.pop());state.labLog=log;window.BenchExperiment?.onDesignLoaded(state.experiment);restoreDisplay();baseline=JSON.stringify(state);dirty=true;clearSelection();alignment=null;recompute();inspect();syncHistory();window.ComponentPacks?.refresh()}
