function add(type,options={}){const b=state.boards[0],count=state.components.filter(c=>c.type===type).length+1,c=component(type,defs[type].name+' '+count,b.x+Math.min(b.cols-1,3+count)*b.spacing,b.y+Math.min(b.rows-1,3+count)*b.spacing,100,['mirror','beamsplitter','dichroic','pbs'].includes(type)?135:0,0,defs[type].defaults.axisAngle||0);if(options.name)c.name=options.name;if(options.params)Object.assign(c.params,options.params);state.components.push(c);clearSelection();selection.add(c.id);commit();recompute();inspect()}
function remove(){if(selection.size){state.components=state.components.filter(c=>!selection.has(c.id))}else if(selectedBoard&&state.boards.length>1){state.boards=state.boards.filter(b=>b.id!==selectedBoard)}else{toast('先选择器件；至少保留一块平台');return}clearSelection();commit();recompute();inspect()}
function snap(p){let nearest=null,best=Infinity;for(const b of state.boards){const x=b.x+O.clamp(Math.round((p[0]-b.x)/b.spacing),0,b.cols-1)*b.spacing,y=b.y+O.clamp(Math.round((p[1]-b.y)/b.spacing),0,b.rows-1)*b.spacing,d=Math.hypot(x-p[0],y-p[1]);if(d<best){best=d;nearest=[x,y,p[2]]}}return best<40?nearest:p}
