function bind(el,obj){el.querySelectorAll('[data-key]').forEach(input=>input.onchange=()=>{const key=input.dataset.key,isNumber=input.type==='number';let value=isNumber?Number(input.value):input.value;if(isNumber&&!Number.isFinite(value)){toast('请输入有限数值');inspect();return}if(key==='z')value=Math.max(0,value);if(key==='pitch')value=O.clamp(value,-90,90);if(['cols','rows'].includes(key))value=O.clamp(Math.round(value),2,100);if(key==='spacing')value=O.clamp(value,1,100);if(key.startsWith('param.')){const k=key.slice(6);if(['aperture','wavelength','waistRadius','pulseWidth','repetitionRate'].includes(k))value=Math.max(.001,value);if(['power','thickness','travel'].includes(k))value=Math.max(0,value);if(k==='ellipticity')value=O.clamp(value,-45,45);obj.params[k]=value;if(k==='targetDelay'){obj.params.travel=Math.max(0,value*.299792458/2);obj.params.targetDelay=2*obj.params.travel/.299792458}if(k==='travel')obj.params.targetDelay=2*value/.299792458}else obj[key]=value;commit();recompute();inspect()})}
function polLabel(p){if(Math.abs(p.ellipticity)<.1)return `线偏振 · 方位 ${p.angle.toFixed(1)}°`;if(Math.abs(p.ellipticity)>44.9)return `圆偏振 · 椭圆率角 ${p.ellipticity.toFixed(1)}°`;return `椭圆偏振 · 方位 ${p.angle.toFixed(1)}° · 椭圆率角 ${p.ellipticity.toFixed(1)}°`}
function showPaths(start=null,end=null){if(!end)end=selection.size===1?[...selection][0]:null;if(!end)return;let rows=result.segments.filter(r=>r.toId===end&&!r.internal);if(start)rows=rows.filter(r=>r.fromId===start||r.sourceId===start||r.path.some(id=>rayById(id)?.fromId===start));const el=$('#pathResult');if(!rows.length){el.textContent='没有光束命中该终点，请检查位置、口径和面朝向。';return}const metrics=rows.map(r=>{let sub=0,totalSub=0,timeSub=0;if(start){const firstSeg=[...r.path,r.id].map(rayById).find(s=>s?.fromId===start);if(firstSeg){sub=firstSeg.opl-firstSeg.length;timeSub=firstSeg.timePs-firstSeg.length/.299792458;totalSub=firstSeg.total-firstSeg.length}}return{r,opl:r.opl-sub,total:r.total-totalSub,time:r.timePs-timeSub}});let html=metrics.map(({r,opl,total,time})=>`<div><strong>${esc(byId(r.sourceId)?.name||'光源')}</strong> · ${r.beam.wavelength.toFixed(1)} nm<br>几何 ${total.toFixed(3)} mm · OPL ${opl.toFixed(3)} mm<br>${time.toFixed(3)} ps · ${O.formatSignal(r.beamEnd.power)} mW</div>`).join('');if(rows.length>1){const times=metrics.map(x=>x.time),dt=Math.max(...times)-Math.min(...times);html+=`<strong class="big">Δt ${dt.toFixed(3)} ps</strong><div>对应双程补偿移动量 ${(dt*.299792458/2).toFixed(4)} mm</div>`}const c=byId(end);if(c?.type==='detector'){const current=rows.reduce((sum,r)=>sum+(r.beam.wavelength>=c.params.minWavelength&&r.beam.wavelength<=c.params.maxWavelength?r.beamEnd.power*1e-3*c.params.responsivity:0),0);html+=`<div>总光电流 ${O.formatSignal(current*1e3)} mA · 预计输出 ${O.formatSignal(current*c.params.transimpedanceGain)} V</div>`}el.innerHTML=html}
function uses(r,id){return r.fromId===id||r.path.some(k=>rayById(k)?.fromId===id)}
function scan(c){const rep=result.reports.find(x=>!x.self&&uses(x.a.ray,c.id)!==uses(x.b.ray,c.id));if(!rep)return{rows:[],error:'扫描需关联：当前延时台只经过 BBO 两路入射光中的一路。'};const p=c.params,a=Number(p.scanStart),b=Number(p.scanEnd),step=Number(p.scanStep);if(![a,b,step].every(Number.isFinite)||step<=0||a===b)return{rows:[],error:'请设置不同的起终点及正步长。'};if(a<0||b<0)return{rows:[],error:'扫描位置为非负的绝对移动量，请将起终点设为 ≥0。'};const n=Math.floor(Math.abs(b-a)/step);if(n>10000)return{rows:[],error:'扫描超过 10000 点，请增大步长。'};const rows=[],sign=uses(rep.a.ray,c.id)?1:-1,base=rep.a.timePs-rep.b.timePs,factor=rep.angleFactor*rep.polFactor*rep.spatial;for(let i=0;i<=n;i++){const x=a+Math.sign(b-a)*i*step,added=2*(x-p.travel)/.299792458,dt=base+sign*added,signal=Math.exp(-4*Math.log(2)*(dt/rep.window)**2)*factor;rows.push({x,added,dt,signal})}return{rows,rep,zero:p.travel-base*.299792458/(2*sign),fwhm:rep.window*.299792458/2}}
function scanHTML(c){const d=scan(c);if(!d.rows.length)return`<div class="readonly">${esc(d.error)}</div>`;const max=Math.max(...d.rows.map(x=>x.signal),1e-15),pts=d.rows.map((r,i)=>`${i/Math.max(1,d.rows.length-1)*240},${74-r.signal/max*62}`).join(' ');return`<div class="readonly">当前光路的简化互相关<svg viewBox="0 0 240 84" class="scan-chart"><polyline points="${pts}"/></svg>预测零延时 ${d.zero.toFixed(4)} mm<br>理论 FWHM ${d.fwhm.toFixed(4)} mm<br>${d.zero<Math.min(c.params.scanStart,c.params.scanEnd)||d.zero>Math.max(c.params.scanStart,c.params.scanEnd)?'零延时位于扫描范围外。':''}${c.params.scanStep>d.fwhm/3?'步长偏大，可能漏采峰值。':''}<button class="wide-btn" data-scan>导出 CSV</button></div>`}
function diagnostics(){const notes=result.warnings.slice();if(result.segments.some(r=>r.weak))notes.push('虚线表示低于 1 nW 的弱光，仍参与传播与探测器计算；显示样式不代表探测器灵敏度。');if(result.segments.some(r=>['pbs','beamsplitter','wollaston'].includes(byId(r.fromId)?.type)))notes.push('光束线宽与亮度按相对功率绘制；分束后的波长标签显示占光源的百分比。');if(state.photoReconstruction)notes.push('照片重建初稿：请在“数据与日志”核对来源、假设和待确认参数。');for(const r of result.segments.filter(r=>r.toId)){const c=byId(r.toId);if(r.edgeWarning)notes.push(`${c.name}：口径透过估算 ${(100*r.clipFraction).toFixed(1)}%。`);if(c.type==='iris')notes.push(`${c.name}：局部偏心 u=${r.hitOffset[0].toFixed(2)}，v=${r.hitOffset[1].toFixed(2)} mm。`);if(c.type==='detector'&&r.beamEnd.power>c.params.saturationPower)notes.push(`${c.name}：超过设定饱和功率。`)}for(const r of result.reports.filter(x=>!x.self))notes.push(`${byId(r.cId).name}（Type-I oo→e）：Δt ${r.dt.toFixed(3)} / ${r.window.toFixed(3)} ps，空间重合 ${(r.spatial*100).toFixed(1)}%，夹角 ${r.cross.toFixed(2)}°；${r.ok?'产生':'未产生'} ${r.wave.toFixed(1)} nm 混频光。`);
if(alignment){const [a,b]=alignment,firsts=result.segments.filter(r=>r.toId===a),pair=firsts.map(r=>[r,result.segments.find(s=>s.toId===b&&s.path.includes(r.id))]).find(x=>x[1]);if(pair){const [r,s]=pair,co1=O.pose(byId(a)),co2=O.pose(byId(b));if(Math.abs(V.dot(co1.n,co2.n))<.999)notes.unshift('双光阑：光阑法线不平行，先统一两光阑朝向。');else{const delta=V.sub(V.sub(s.b,O.position(byId(b))),V.sub(r.b,O.position(byId(a)))),L=Math.max(.001,s.total-r.total);notes.unshift(`双光阑：近场偏心 ${V.len(V.sub(r.b,O.position(byId(a)))).toFixed(2)} mm；相对角误差 u=${(1000*V.dot(delta,co1.u)/L).toFixed(2)}，v=${(1000*V.dot(delta,co1.v)/L).toFixed(2)} mrad。`)}}else notes.unshift('双光阑：未找到依次命中两个光阑的同一分支。')}
$('#diagnosticResult').innerHTML=notes.length?notes.slice(0,24).map(s=>`<div>${esc(s)}</div>`).join(''):'<p>三维追迹已就绪。点击光段查看偏振横截面。</p>'}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function displaySettings(){return{showBoards:view.showBoards,showNames:view.showNames,showWavelengths:view.showWavelengths,polarization:view.polarization,labels:view.labels}}
function restoreDisplay(){const d=state.display||{};for(const [id,key]of [['boardVisBtn','showBoards'],['namesBtn','showNames'],['waveBtn','showWavelengths'],['polBtn','polarization'],['labelsBtn','labels']]){view[key]=d[key]!==false;$('#'+id).classList.toggle('active',view[key]);$('#'+id).setAttribute?.('aria-pressed',String(view[key]))}}
function snapshot(){const s={...state,display:displaySettings(),view3d:clone(view.camera)};return window.SheetCore?SheetCore.sync(s):s}
function save(){try{localStorage.setItem('optical-bench-design-v8',JSON.stringify(snapshot()));dirty=false;toast('三维设计已保存在本机浏览器')}catch{toast('浏览器存储不可用，请导出 JSON 保存')}}
function loadDesign(data){const s=O.migrate(data,defs);state=s;window.BenchExperiment?.onDesignLoaded(s.experiment);restoreDisplay();clearSelection();alignment=null;commit();recompute();if(s.view3d&&Number.isFinite(s.view3d.az)&&Number.isFinite(s.view3d.el)&&Array.isArray(s.view3d.target)&&s.view3d.target.length===3&&s.view3d.target.every(Number.isFinite)){Object.assign(view.camera,s.view3d);view.camera.zoom=O.clamp(view.camera.zoom,.1,6);view.dirty=true}else view.fit();inspect();window.ComponentPacks?.refresh();if(data.version<8)toast('已迁移位置、镜面角和波片快轴；请检查透射器件面朝向')}
function setMode(value){mode=mode===value?null:value;first=null;$('#measureBtn').classList.toggle('active',mode==='measure');$('#alignBtn').classList.toggle('active',mode==='align');$('#moveBoardBtn').classList.toggle('active',mode==='board');$('#orbitBtn').classList.toggle('active',mode==='orbit');status(mode==='orbit'?'旋转视角模式：左键拖动；再次点击按钮或 Esc 返回搭建':mode==='measure'?'依次点击起点器件、终点器件':mode==='align'?'依次点击近场、远场光阑':mode==='board'?'拖动平台，器件随平台一起移动':'左键拖器件 · Alt 拖动旋转 · Ctrl 拖动平移')}
function pointer(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function planePoint(p,anchor){const {n,u,v}=view.axes(),x=(p.x-view.w/2-view.camera.panX)/view.camera.zoom,y=-(p.y-view.h/2-view.camera.panY)/view.camera.zoom,q=V.add(view.camera.target,V.add(V.mul(u,x),V.mul(v,y))),axis=Math.abs(n[2])>.05?2:Math.abs(n[1])>.1?1:0;return V.add(q,V.mul(n,(anchor[axis]-q[axis])/n[axis]))}
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;const p=pointer(e);canvas.focus();canvas.setPointerCapture(e.pointerId);$('#tooltip').style.display='none';if(e.ctrlKey||e.metaKey||e.button===1){gesture={type:'pan',p,px:view.camera.panX,py:view.camera.panY};e.preventDefault();return}if(e.altKey||(mode==='orbit'&&!window.recordingPick)){gesture={type:'orbit',p,az:view.camera.az,el:view.camera.el};e.preventDefault();return}const hit=view.pick(p);if(e.shiftKey&&hit?.kind!=='component'){gesture={type:'box',p,add:true};return}if(hit?.kind==='component'){const modeBefore=mode;select(hit,e.shiftKey);if(modeBefore||e.shiftKey||window.recordingPick)return;const c=byId(hit.id),anchor=O.position(c);gesture={type:'move',p,anchor,world:planePoint(p,anchor),items:[...selection].map(id=>({id,pos:O.position(byId(id))})),zOnly:$('#moveZBtn').classList.contains('active')};return}if(hit?.kind==='board'&&mode==='board'){select(hit);const b=state.boards.find(x=>x.id===hit.id),items=state.components.filter(c=>c.x>=b.x-16&&c.x<=b.x+(b.cols-1)*b.spacing+16&&c.y>=b.y-16&&c.y<=b.y+(b.rows-1)*b.spacing+16).map(c=>({id:c.id,pos:O.position(c)}));gesture={type:'board',p,anchor:[b.x,b.y,0],world:planePoint(p,[b.x,b.y,0]),id:b.id,items};return}if(hit){select(hit);return}clearSelection();inspect();redraw();gesture={type:'box',p,add:false}});
canvas.addEventListener('pointermove',e=>{const p=pointer(e),g=gesture;if(!g){const hit=view.pick(p);canvas.style.cursor=hit?.kind==='component'?'move':hit?.kind==='ray'?'pointer':'default';const r=hit?.kind==='ray'?rayById(hit.id):null;if(r){$('#tooltip').innerHTML=`<strong>${r.beam.wavelength.toFixed(1)} nm · ${O.formatSignal(r.beamEnd.power)} mW（光源 ${(100*sourceShare(r)).toFixed(1)}%）${r.beam.mode?' · BBO '+r.beam.mode:''}</strong><br>${r.length.toFixed(3)} mm · ${esc(polLabel(O.polState(r.beam.field,r.d)))}`;$('#tooltip').style.display='block';$('#tooltip').style.left=Math.min(innerWidth-275,e.clientX+12)+'px';$('#tooltip').style.top=Math.min(innerHeight-95,e.clientY+12)+'px'}else $('#tooltip').style.display='none';return}const dx=p.x-g.p.x,dy=p.y-g.p.y;g.moved=Math.hypot(dx,dy)>3||g.moved;
if(g.type==='pan'){view.camera.panX=g.px+dx;view.camera.panY=g.py+dy;view.dirty=true}else if(g.type==='orbit'){view.camera.az=g.az-dx*.35;view.camera.el=O.clamp(g.el+dy*.35,0,90);view.dirty=true}else if(g.type==='box'){view.rectangle={x:Math.min(g.p.x,p.x),y:Math.min(g.p.y,p.y),w:Math.abs(dx),h:Math.abs(dy)}}else if(g.type==='move'||g.type==='board'){if(!g.moved)return;let delta=g.zOnly?[0,0,-dy/view.camera.zoom]:V.sub(planePoint(p,g.anchor),g.world);if(g.type==='board')delta[2]=0;const minZ=Math.min(...g.items.map(it=>it.pos[2]));delta[2]=Math.max(delta[2],-minZ);for(const it of g.items){const c=byId(it.id);[c.x,c.y,c.z]=V.add(it.pos,delta)}if(g.type==='board'){const b=state.boards.find(b=>b.id===g.id);b.x=g.anchor[0]+delta[0];b.y=g.anchor[1]+delta[1]}recompute()}});
function finish(e,cancel=false){const g=gesture;if(!g)return;gesture=null;if(g.type==='move'||g.type==='board'){if(cancel){for(const it of g.items){const c=byId(it.id);[c.x,c.y,c.z]=it.pos}if(g.type==='board'){const b=state.boards.find(b=>b.id===g.id);[b.x,b.y]=g.anchor}}else if(g.moved){if(g.type==='move'&&!g.zOnly&&$('#snapBtn').classList.contains('active')){const c=byId(g.items[0].id),d=V.sub(snap(O.position(c)),O.position(c));for(const it of g.items){const c=byId(it.id);c.x+=d[0];c.y+=d[1]}}if(g.type==='board'){const b=state.boards.find(b=>b.id===g.id),ref=state.boards.find(b=>b.id!==g.id),sp=ref?.spacing||b.spacing,origin=ref?[ref.x,ref.y]:[0,0],x=origin[0]+Math.round((b.x-origin[0])/sp)*sp,y=origin[1]+Math.round((b.y-origin[1])/sp)*sp,dx=x-b.x,dy=y-b.y;b.x=x;b.y=y;for(const it of g.items){const c=byId(it.id);c.x+=dx;c.y+=dy}}commit()}recompute();inspect()}if(g.type==='box'){const r=view.rectangle;if(r&&!cancel){if(!g.add)selection.clear();for(const c of state.components){const p=view.project(O.position(c));if(p.x>=r.x&&p.x<=r.x+r.w&&p.y>=r.y&&p.y<=r.y+r.h)selection.add(c.id)}selectedBoard=null;selectedRay=null;inspect();redraw()}view.rectangle=null}if(e&&canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId)}
canvas.addEventListener('pointerup',e=>finish(e));canvas.addEventListener('pointercancel',e=>finish(e,true));canvas.addEventListener('lostpointercapture',e=>{if(gesture)finish(e,true)});
canvas.addEventListener('wheel',e=>{e.preventDefault();const p=pointer(e),before=view.camera.zoom,next=O.clamp(before*Math.exp(-e.deltaY*.001),.1,6),factor=next/before;view.camera.panX=p.x-view.w/2-(p.x-view.w/2-view.camera.panX)*factor;view.camera.panY=p.y-view.h/2-(p.y-view.h/2-view.camera.panY)*factor;view.camera.zoom=next;view.dirty=true;$('#zoomText').textContent=Math.round(next*100)+'%'},{passive:false});
Object.entries(defs).filter(([type])=>type!=='sample').forEach(([type,d])=>{const b=document.createElement('button');b.className='component-card';b.innerHTML=`<span class="icon">${esc(d.icon)}</span><span>${esc(d.name)}</span>`;b.onclick=()=>window.ComponentPicker.open(type);$('#componentLibrary').appendChild(b)});
$('#undoBtn').onclick=()=>undo();$('#redoBtn').onclick=()=>undo(true);$('#deleteBtn').onclick=remove;$('#rotateBtn').onclick=()=>{for(const id of selection){const c=byId(id);if(c.type==='qwp')c.roll+=5;else c.yaw+=5}commit();recompute();inspect()};$('#measureBtn').onclick=()=>setMode('measure');$('#alignBtn').onclick=()=>setMode('align');$('#moveBoardBtn').onclick=()=>setMode('board');$('#orbitBtn').onclick=()=>setMode('orbit');$('#rayToggleBtn').onclick=()=>{state.showRays=!state.showRays;commit();recompute();inspect()};$('#saveBtn').onclick=save;$('#exportBtn').onclick=()=>download('optical-bench-v8-3d.json',JSON.stringify(snapshot(),null,2));
