$('#addBoardBtn').onclick=()=>{state.boards.push({id:uid(),x:100+state.boards.length*100,y:100+state.boards.length*100,cols:O.clamp(Math.round(Number($('#boardCols').value)||24),2,100),rows:O.clamp(Math.round(Number($('#boardRows').value)||16),2,100),spacing:O.clamp(Number($('#holeSpacing').value)||25,1,100)});commit();recompute();view.fit()};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view.preset(b.dataset.view);$('#zoomText').textContent=Math.round(view.camera.zoom*100)+'%'});$('#fitBtn').onclick=()=>view.fit();$('#animateBtn').onclick=e=>{view.animate=!view.animate;e.currentTarget.classList.toggle('active',view.animate);e.currentTarget.textContent=view.animate?'暂停偏振':'播放偏振'};$('#snapBtn').onclick=e=>e.currentTarget.classList.toggle('active');$('#moveZBtn').onclick=e=>e.currentTarget.classList.toggle('active');$('#demoBtn').onclick=()=>{state=demo();window.BenchExperiment?.onDesignLoaded(null);clearSelection();commit();recompute();view.preset('iso');inspect();toast('已载入三维示例，可撤销回原设计')};
for(const [id,key]of [['boardVisBtn','showBoards'],['namesBtn','showNames'],['waveBtn','showWavelengths'],['polBtn','polarization'],['labelsBtn','labels']])$('#'+id).onclick=()=>{view[key]=!view[key];state.display=displaySettings();commit();restoreDisplay();redraw()};

window.addEventListener('keydown',e=>{if(window.experimentLocked)return;if(e.target.matches('input,select,textarea')||e.target.isContentEditable)return;const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();undo(e.shiftKey);return}if((e.ctrlKey||e.metaKey)&&key==='y'){e.preventDefault();undo(true);return}if((e.ctrlKey||e.metaKey)&&key==='s'){e.preventDefault();save();return}if(e.ctrlKey||e.metaKey)return;if(key==='delete'||key==='backspace'){e.preventDefault();remove()}if(key==='escape'){finish(null,true);setMode(null)}if(key==='r')$('#rotateBtn').click();if(key==='m')setMode('measure');if(key==='a')setMode('align');if(key==='b')$('#rayToggleBtn').click();if(key==='f')view.fit();if(key==='1')view.preset('iso');if(key==='2')view.preset('top');if(key==='3')view.preset('front');if(key==='4')view.preset('side')});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
function paintPol(time){const el=$('#polCanvas'),r=rayById(selectedRay);if(!el||!r)return;const ctx=el.getContext('2d'),{u,v}=O.basis(r.d),f=r.beam.field,project=t=>({x:120+65*(V.dot(f.re,u)*Math.cos(t)+V.dot(f.im,u)*Math.sin(t)),y:95-65*(V.dot(f.re,v)*Math.cos(t)+V.dot(f.im,v)*Math.sin(t))});ctx.clearRect(0,0,240,190);ctx.strokeStyle='#c5d1db';ctx.beginPath();ctx.moveTo(25,95);ctx.lineTo(215,95);ctx.moveTo(120,15);ctx.lineTo(120,175);ctx.stroke();ctx.strokeStyle='#007f78';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<=80;i++){const p=project(i*Math.PI/40);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.stroke();const p=project(view.animate?time*.002:0);ctx.beginPath();ctx.moveTo(120,95);ctx.lineTo(p.x,p.y);ctx.strokeStyle='#203c57';ctx.stroke();ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fillStyle='#203c57';ctx.fill();ctx.font='12px sans-serif';ctx.fillStyle='#486479';ctx.fillText('u',220,99);ctx.fillText('v',125,16)}
function resize(){const rect=$('#workspace').getBoundingClientRect();view.resize(rect.width,rect.height,Math.min(devicePixelRatio||1,2))}
